CREATE TABLE IF NOT EXISTS result_edits(match_id TEXT PRIMARY KEY,team_id TEXT NOT NULL,home_score INTEGER,away_score INTEGER,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),revision INTEGER NOT NULL,updated_at INTEGER NOT NULL,change_id TEXT NOT NULL,CHECK(active=0 OR (home_score BETWEEN 0 AND 99 AND away_score BETWEEN 0 AND 99)));
CREATE TABLE IF NOT EXISTS result_edit_history(id TEXT PRIMARY KEY,match_id TEXT NOT NULL,team_id TEXT NOT NULL,revision INTEGER NOT NULL,home_score INTEGER,away_score INTEGER,previous_home INTEGER,previous_away INTEGER,action TEXT NOT NULL,actor_uid TEXT NOT NULL,actor_email TEXT NOT NULL,actor_name TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(match_id,revision));
CREATE INDEX IF NOT EXISTS result_history_match ON result_edit_history(match_id,revision DESC);
